const note = sticky("## SynthIQ - evidence search for medical students\nPOST /webhook/Y2Workplace/svc/synthiq with {message, model, conversationId, context:{sources,years,types,openAccess,perSource}} plus X-Guest-Id or a bearer token.\n\nPrepare Search identifies the caller and sanitises the source picks. Fetch Papers queries only the chosen sources - Europe PMC for PubMed/MEDLINE, PubMed Central, Cochrane reviews and preprints, the ClinicalTrials.gov API for registered trials and Crossref for other journals - and keeps at most 14 de-duplicated records. Build Prompt applies the daily limit and the free / premium tiers, then writes the prompt around those records so every claim can be cited as [P1], [P2]. Format Reply keeps only the citations the answer actually used and logs the run into ys_agent_runs / ys_usage / ys_activity, exactly like Y Square Agents.\n\nSeparate from Y Square Agents on purpose: retrieval problems here cannot affect Athlete Edge, StudyPals or Event Planner.", { position: [0, -300], width: 620, height: 300, color: 4 });

export default workflow('ysquare-synthiq', 'Y Square SynthIQ')
